import { Container, getContainer } from "@cloudflare/containers";

interface Env {
  DBT_CONTAINER: DurableObjectNamespace<DbtContainer>;
  DBT_ARTIFACTS: R2Bucket;
  DATABRICKS_HOST: string;
  DATABRICKS_HTTP_PATH: string;
  DATABRICKS_TOKEN: string;
}

export class DbtContainer extends Container<Env> {
  defaultPort = 8080;

  // dbt run は数分かかるため、十分なアイドル時間を確保
  sleepAfter = "5m";

  envVars = {
    DATABRICKS_HOST: this.env.DATABRICKS_HOST,
    DATABRICKS_HTTP_PATH: this.env.DATABRICKS_HTTP_PATH,
    DATABRICKS_TOKEN: this.env.DATABRICKS_TOKEN,
  };

  override onStart() {
    console.log("dbt-runner container started");
  }

  override onStop() {
    console.log("dbt-runner container stopped");
  }

  override onError(error: unknown) {
    console.error("dbt-runner container error:", error);
  }
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);
    const path = url.pathname;

    // Health check
    if (path === "/health") {
      return Response.json({ status: "ok" });
    }

    // Get or create container instance
    const container = getContainer(env.DBT_CONTAINER, "dbt-runner-main");

    // dbt commands: POST /run, /seed, /test, /build
    if (request.method === "POST" && ["/run", "/seed", "/test", "/build"].includes(path)) {
      const body = await request.json().catch(() => ({}));
      const response = await container.fetch(`http://container${path}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      const result = (await response.json()) as Record<string, unknown>;

      // dbt run/build の成功後、アーティファクトを R2 に保存
      if ((path === "/run" || path === "/build") && result.returncode === 0) {
        await saveArtifactsToR2(container, env.DBT_ARTIFACTS);
      }

      return Response.json(result);
    }

    // アーティファクト取得 (R2 から)
    if (path.startsWith("/artifacts/")) {
      const key = path.replace("/artifacts/", "");
      const object = await env.DBT_ARTIFACTS.get(`dbt-core/${key}`);
      if (!object) {
        return Response.json({ error: "not found" }, { status: 404 });
      }
      return new Response(object.body, {
        headers: { "Content-Type": "application/json" },
      });
    }

    return Response.json({ error: "not found" }, { status: 404 });
  },
};

async function saveArtifactsToR2(
  container: DurableObjectStub<DbtContainer>,
  bucket: R2Bucket
) {
  try {
    const response = await container.fetch("http://container/artifacts", {
      method: "POST",
    });
    const data = (await response.json()) as {
      artifacts: string[];
      data: Record<string, unknown>;
    };

    const timestamp = new Date().toISOString().replace(/[:.]/g, "-");

    for (const [filename, content] of Object.entries(data.data)) {
      // 最新版を保存
      await bucket.put(`dbt-core/latest/${filename}`, JSON.stringify(content), {
        httpMetadata: { contentType: "application/json" },
      });

      // タイムスタンプ付きアーカイブ
      await bucket.put(
        `dbt-core/history/${timestamp}/${filename}`,
        JSON.stringify(content),
        { httpMetadata: { contentType: "application/json" } }
      );
    }

    console.log(
      `Saved ${data.artifacts.length} artifacts to R2: ${data.artifacts.join(", ")}`
    );
  } catch (error) {
    console.error("Failed to save artifacts to R2:", error);
  }
}

