"""Lightweight HTTP server for dbt commands inside Cloudflare Container."""

import json
import os
import subprocess
import glob
from http.server import HTTPServer, BaseHTTPRequestHandler


class DbtHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/health":
            self._json_response(200, {"status": "ok"})
        else:
            self._json_response(404, {"error": "not found"})

    def do_POST(self):
        if self.path == "/run":
            self._run_dbt("run")
        elif self.path == "/seed":
            self._run_dbt("seed")
        elif self.path == "/test":
            self._run_dbt("test")
        elif self.path == "/build":
            self._run_dbt("build")
        elif self.path == "/artifacts":
            self._get_artifacts()
        else:
            self._json_response(404, {"error": "not found"})

    def _run_dbt(self, command: str):
        content_length = int(self.headers.get("Content-Length", 0))
        body = json.loads(self.rfile.read(content_length)) if content_length > 0 else {}

        target = body.get("target", "dev")
        select = body.get("select", None)
        full_refresh = body.get("full_refresh", False)

        cmd = ["uv", "run", "dbt", command, "--target", target, "--profiles-dir", "."]
        if select:
            cmd.extend(["--select", select])
        if full_refresh:
            cmd.append("--full-refresh")

        result = subprocess.run(cmd, capture_output=True, text=True, cwd="/app")

        self._json_response(
            200 if result.returncode == 0 else 500,
            {
                "command": command,
                "returncode": result.returncode,
                "stdout": result.stdout,
                "stderr": result.stderr,
            },
        )

    def _get_artifacts(self):
        """Return dbt artifacts (manifest.json, run_results.json, etc.)."""
        artifacts = {}
        artifact_files = [
            "target/manifest.json",
            "target/run_results.json",
            "target/catalog.json",
            "target/sources.json",
        ]
        for path in artifact_files:
            full_path = os.path.join("/app", path)
            if os.path.exists(full_path):
                with open(full_path) as f:
                    artifacts[os.path.basename(path)] = json.load(f)

        self._json_response(200, {"artifacts": list(artifacts.keys()), "data": artifacts})

    def _json_response(self, status: int, body: dict):
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        self.wfile.write(json.dumps(body).encode())


if __name__ == "__main__":
    port = int(os.environ.get("PORT", "8080"))
    server = HTTPServer(("0.0.0.0", port), DbtHandler)
    print(f"dbt-runner server listening on port {port}")
    server.serve_forever()

